import math

def ucb_pick(counts, means, t, c):
    for a, n in enumerate(counts):
        if n == 0:
            return a
    scores = [means[a] + c * math.sqrt(math.log(t) / counts[a]) for a in range(len(counts))]
    return max(range(len(scores)), key=lambda a: scores[a])

